/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def guardrails_safety_filter(input_data: dict) -> dict:
    """
    فلتر الأمان لكشف محاولات الـ Prompt Injection والمدخلات الضارة.

    Enterprise guardrails that detect prompt injection attempts in both
    Arabic and English before the message reaches the LLM.

    Args:
        input_data: Normalized ingress data with sanitized_message.

    Returns:
        Input data augmented with guardrail_safe and flagged_reason.
    """
    raw_msg = input_data.get("sanitized_message") or input_data.get(
        "customer_message", "Hello"
    )

    injection_patterns = [
        r"ignore\s+(all\s+)?(previous|prior|above)\s+instructions",
        r"system\s*prompt",
        r"jailbreak",
        r"bypass\s+rules",
        r"disregard\s+guidelines",
    ]

    prompt_injection = False
    for pattern in injection_patterns:
        if re.search(pattern, raw_msg, re.IGNORECASE):
            prompt_injection = True
            break

    return {
        **input_data,
        "guardrail_safe": not prompt_injection,
        "flagged_reason": "prompt_injection_attempt" if prompt_injection else None,
    }


# ==============================================================================
# 4. WORKFLOW 03 — Build Prompt Payload
# Node: "Build Prompt Payload"
# Purpose: Constructs the structured LLM prompt with FAQ context, conversation
#          history, and strict response-format instructions. If guardrails
#          flagged the input, returns a deflection immediately.
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const input = $input.first()?.json || {};
const rawMsg = input.sanitized_message || input.customer_message || 'Hello';

// Enterprise Guardrails: Detect Prompt Injection and Harmful Input
const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
  /system\s*prompt/i,
  /jailbreak/i,
  /bypass\s+rules/i,
  /disregard\s+guidelines/i
];

let promptInjection = false;
for (const pattern of injectionPatterns) {
  if (pattern.test(rawMsg)) {
    promptInjection = true;
    break;
  }
}

return [{
  json: {
    ...input,
    guardrail_safe: !promptInjection,
    flagged_reason: promptInjection ? 'prompt_injection_attempt' : null
  }
}];

const item = $input.first()?.json || {};
const customerMsg = item.sanitized_message || item.customer_message || 'Hello';
const locale = item.locale || (customerMsg.match(/[\u0600-\u06FF]/) ? 'ar' : 'en');
const history = (item.conversation_history || []).slice(-3).map(h => h.sender_type + ': ' + h.content).join('\n');
const msg = customerMsg.toLowerCase();

// === KEYWORD PRE-CLASSIFIER (reliable for Arabic + English) ===
const escalationKeywords = [
  ' شكوى', 'مشكلة', 'ضايق', 'زعلان', 'غاضب', 'سيء', 'سء ', 'موظف', 'ممثل', 'مدير',
  'كلمني حد', 'تحكي مع', 'complaint', 'frustrated', 'angry', 'terrible', 'worst',
  'agent', 'manager', 'representative', 'human', 'speak to', 'talk to', 'escalate'
];
const orderKeywords = [
  'تتبع', 'حالة طلب', 'طلب خدمة', 'رقم طلب', 'رقم التتبع', ' SRV-', ' ORD-',
  'track', 'tracking', 'shipment', 'status of', 'order number', 'my order'
];
const faqKeywords = [
  'شروط', 'تقديم', 'تسجيل', 'تخصص', 'مسار', 'امتحان', 'دراسة', 'شهادة', 'منح',
  'رسوم', 'مؤهل', ' SEB', 'LMS', 'إنسحاب', 'admission', 'requirement', 'course',
  'program', 'apply', 'registration', 'scholarship', 'track', 'certificate', 'study',
  'exam', 'eligible', 'document', 'fee', 'cost', 'eligib', 'debi', 'digilians', 'رواد', 'بناة', 'فرق', 'مقارنة', 'مقارنه'
];

let keywordIntent = null;

if (escalationKeywords.some(kw => msg.includes(kw))) {
  keywordIntent = 'human_escalation';
} else if (orderKeywords.some(kw => msg.includes(kw))) {
  keywordIntent = 'order_lookup';
} else if (faqKeywords.some(kw => msg.includes(kw))) {
  keywordIntent = 'faq_query';
}

// If keyword classifier matched, bypass LLM entirely
if (keywordIntent) {
  return [{
    json: {
      direct_bypass: true,
      ai_output: {
        intent: keywordIntent,
        confidence: 0.9,
        entities: keywordIntent === 'order_lookup' ? { order_number: (customerMsg.match(/SRV-\d+|ORD-\d+/i) || [null])[0] } : {},
        sentiment: 'neutral',
        requires_human: keywordIntent === 'human_escalation',
        direct_response: ''
      },
      customer_message: customerMsg,
      locale: locale
    }
  }];
}

// === LLM FALLBACK (only for ambiguous messages) ===
const promptText = 'Classify this customer message into ONE intent. Reply ONLY with valid JSON.\n\n' +
  'Intents:\n' +
  '- faq_query: Questions about programs, admission, tracks, registration, exams\n' +
  '- order_lookup: Asking about order/service status or tracking number\n' +
  '- human_escalation: Angry customer, complaint, wants human agent\n' +
  '- general_support: Greetings, thanks, small talk\n\n' +
  'Examples:\n' +
  'Message: Hello -> {\"intent\":\"general_support\",\"confidence\":1.0}\n' +
  'Message: What are the requirements -> {\"intent\":\"faq_query\",\"confidence\":0.95}\n' +
  'Message: I want to complain -> {\"intent\":\"human_escalation\",\"confidence\":0.95}\n\n' +
  'Response format: {\"intent\":\"...\",\"confidence\":0.9,\"entities\":{},\"sentiment\":\"positive|neutral|frustrated\",\"requires_human\":false,\"direct_response\":\"\"}\n\n' +
  (history ? 'Previous conversation:\n' + history + '\n\n' : '') +
  'Customer message: ' + JSON.stringify(customerMsg);

return [{
  json: {
    ollama_body: {
      model: 'qwen2.5:3b',
      prompt: promptText,
      stream: false,
      options: { temperature: 0.1, num_predict: 200, num_ctx: 2048 }
    },
    locale: locale,
    customer_message: customerMsg,
    guardrail_safe: item.guardrail_safe !== false,
    use_llm: true
  }
}];

/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def parse_and_validate_ai_schema(
    raw_response: Optional[str], build_data: dict
) -> dict:
    """
    تحليل رد الذكاء الاصطناعي والتحقق من صحة بنية الـ JSON، مع تصنيف
    احتياطي (Heuristic) في حال فشل الـ LLM.

    Parses the raw Ollama response, validates JSON schema, and applies
    heuristic fallback classification when the LLM output is malformed.

    Args:
        raw_response: Raw text response from Ollama.
        build_data: Original build payload with customer context.

    Returns:
        Dict with validated ai_output and customer context.
    """
    if build_data.get("direct_bypass"):
        return {
            "ai_output": build_data["ai_output"],
            "customer_message": build_data.get("customer_message"),
            "customer": build_data.get("customer"),
            "conversation": build_data.get("conversation"),
            "channel": build_data.get("channel"),
            "channel_user_id": build_data.get("channel_user_id"),
            "locale": build_data.get("locale"),
        }

    original_msg = (build_data.get("customer_message") or "").lower()
    locale = build_data.get("locale", "ar")
    is_ar = locale == "ar"

    parsed = None
    if raw_response:
        try:
            clean_json = re.sub(r"```json|```", "", raw_response).strip()
            match = re.search(r"\{[\s\S]*\}", clean_json)
            if match:
                clean_json = match.group(0)
            parsed = json.loads(clean_json)
        except (json.JSONDecodeError, TypeError):
            parsed = None

    # Heuristic Fail-Safe
    if not parsed or "intent" not in parsed:
        order_keywords = ["order", "srv-", "ord-", "طلب", "شحن", "تتبع"]
        escalation_keywords = ["human", "supervisor", "angry", "موظف", "مشرف", "شكوى", "إنسان"]
        faq_keywords = ["skill", "policy", "hours", "مهارات", "ساعات", "شروط", "تقديم", "خدمات"]

        if any(kw in original_msg for kw in escalation_keywords):
            parsed = {
                "intent": "human_escalation",
                "confidence": 0.95,
                "entities": {},
                "sentiment": "frustrated",
                "requires_human": True,
                "direct_response": (
                    "يتم الآن تحويلك إلى ممثل خدمة العملاء المختص لمساعدتك..."
                    if is_ar
                    else "Connecting you with a human support specialist..."
                ),
            }
        elif any(kw in original_msg for kw in order_keywords):
            match = re.search(r"(?:ord|srv)-\d+", original_msg, re.IGNORECASE)
            parsed = {
                "intent": "order_lookup",
                "confidence": 0.90,
                "entities": {"order_number": match.group(0).upper() if match else "SRV-1001"},
                "sentiment": "neutral",
                "requires_human": False,
                "direct_response": (
                    "جاري الاستعلام عن بيانات ومسار شحنتك/طلبك..."
                    if is_ar
                    else "Looking up your service request details..."
                ),
            }
        elif any(kw in original_msg for kw in faq_keywords):
            parsed = {
                "intent": "faq_query",
                "confidence": 0.90,
                "entities": {},
                "sentiment": "neutral",
                "requires_human": False,
                "direct_response": (
                    "جاري البحث في قاعدة المعرفة والخدمات المعتمدة..."
                    if is_ar
                    else "Searching the official knowledge base..."
                ),
            }
        else:
            parsed = {
                "intent": "general_support",
                "confidence": 0.85,
                "entities": {},
                "sentiment": "neutral",
                "requires_human": False,
                "direct_response": (
                    "أهلاً وسهلاً بك في منصة خدمة العملاء لمبادرة الرواد الرقميون (DEPI). كيف يمكننا خدمتك اليوم؟"
                    if is_ar
                    else "Welcome to the DEPI Customer Service platform. How may we assist you today?"
                ),
            }

    # Entity extraction fallback
    if not parsed.get("entities"):
        parsed["entities"] = {}
    if not parsed["entities"].get("order_number"):
        match = re.search(r"(?:ord|srv)-\d+", original_msg, re.IGNORECASE)
        if match:
            parsed["entities"]["order_number"] = match.group(0).upper()

    return {
        "ai_output": parsed,
        "customer_message": build_data.get("customer_message"),
        "customer": build_data.get("customer"),
        "conversation": build_data.get("conversation"),
        "channel": build_data.get("channel"),
        "channel_user_id": build_data.get("channel_user_id"),
        "locale": locale,
    }


# ==============================================================================
# 6. WORKFLOW 01 — General Support Handler
# Node: "General Support Handler"
# Purpose: Generates a professional welcome message with available services
#          when the AI classifies the intent as general_support.
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const nodeInput = $input.first()?.json || {};
const buildData = $('Build Prompt Payload').first()?.json || {};

if (buildData.direct_bypass) {
  return [{
    json: {
      ai_output: buildData.ai_output,
      customer_message: buildData.customer_message,
      customer: buildData.customer,
      conversation: buildData.conversation,
      channel: buildData.channel,
      channel_user_id: buildData.channel_user_id,
      locale: buildData.locale
    }
  }];
}

const rawResponse = nodeInput.response;
const originalMsg = (buildData.customer_message || '').toLowerCase();
const locale = buildData.locale || 'ar';
const isAr = locale === 'ar';

let parsed = null;
try {
  if (rawResponse) {
    let cleanJson = rawResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = cleanJson.match(/\{[\s\S]*\}/);
    if (match) cleanJson = match[0];
    parsed = JSON.parse(cleanJson);
  }
} catch (e) {
  parsed = null;
}

// Enterprise Heuristic Fail-Safe
if (!parsed || !parsed.intent) {
  const isOrder = originalMsg.includes('order') || originalMsg.includes('srv-') || originalMsg.includes('ord-') || originalMsg.includes('طلب') || originalMsg.includes('شحن') || originalMsg.includes('تتبع');
  const isEscalation = originalMsg.includes('human') || originalMsg.includes('supervisor') || originalMsg.includes('angry') || originalMsg.includes('complaint') || originalMsg.includes('frustrated') || originalMsg.includes('angry') || originalMsg.includes('speak to') || originalMsg.includes('talk to') || originalMsg.includes('representative') || originalMsg.includes('manager') || originalMsg.includes('موظف') || originalMsg.includes('مشرف') || originalMsg.includes('شكوى') || originalMsg.includes('إنسان') || originalMsg.includes('叫声') || originalMsg.includes('متضايق');
  const isFaq = originalMsg.includes('skill') || originalMsg.includes('policy') || originalMsg.includes('hours') || originalMsg.includes('admission') || originalMsg.includes('requirement') || originalMsg.includes('course') || originalMsg.includes('program') || originalMsg.includes('apply') || originalMsg.includes('registration') || originalMsg.includes('scholarship') || originalMsg.includes('track') || originalMsg.includes('certificate') || originalMsg.includes('study') || originalMsg.includes('exam') || originalMsg.includes('available') || originalMsg.includes('eligib') || originalMsg.includes('document') || originalMsg.includes('مهارات') || originalMsg.includes('ساعات') || originalMsg.includes('شروط') || originalMsg.includes('تقديم') || originalMsg.includes('خدمات') || originalMsg.includes('الخدمات') || originalMsg.includes('توقيع') || originalMsg.includes('رواد') || originalMsg.includes('رقميون') || originalMsg.includes('depi') || originalMsg.includes('مسار') || originalMsg.includes('تخصص') || originalMsg.includes('تسجيل') || originalMsg.includes('امتحان') || originalMsg.includes('seb') || originalMsg.includes('شهادة') || originalMsg.includes('اقامة') || originalMsg.includes('مزايا') || originalMsg.includes('منحة');

  if (isEscalation) {
    parsed = {
      intent: 'human_escalation',
      confidence: 0.95,
      entities: {},
      sentiment: 'frustrated',
      requires_human: true,
      direct_response: isAr ? 'يتم الآن تحويلك إلى ممثل خدمة العملاء المختص لمساعدتك...' : 'Connecting you with a human support specialist...'
    };
  } else if (isOrder) {
    const match = originalMsg.match(/(?:ord|srv)-\d+/i);
    parsed = {
      intent: 'order_lookup',
      confidence: 0.90,
      entities: { order_number: match ? match[0].toUpperCase() : 'SRV-1001' },
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري الاستعلام عن بيانات ومسار شحنتك/طلبك...' : 'Looking up your service request details...'
    };
  } else if (isFaq) {
    parsed = {
      intent: 'faq_query',
      confidence: 0.90,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري البحث في قاعدة المعرفة والخدمات المعتمدة...' : 'Searching the official knowledge base...'
    };
  } else {
    parsed = {
      intent: 'general_support',
      confidence: 0.85,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr
        ? 'أهلاً وسهلاً بك في منصة خدمة العملاء لمبادرة الرواد الرقميون (DEPI). كيف يمكننا خدمتك اليوم؟'
        : 'Welcome to the DEPI Customer Service platform. How may we assist you today?'
    };
  }
}

if (!parsed.entities) { parsed.entities = {}; }
if (!parsed.entities.order_number) {
  const match = originalMsg.match(/(?:ord|srv)-\d+/i);
  if (match) { parsed.entities.order_number = match[0].toUpperCase(); }
}

return [{
  json: {
    ai_output: parsed,
    customer_message: buildData.customer_message,
    customer: buildData.customer,
    conversation: buildData.conversation,
    channel: buildData.channel,
    channel_user_id: buildData.channel_user_id,
    locale: locale
  }
}];
